import{_ as d,o as a,c as e,a2 as r}from"./chunks/framework.kOe0DhAP.js";const _=JSON.parse('{"title":"异常处理与一致性保障","description":"用订单、成交和账务事实共同判断结果。","frontmatter":{"title":"异常处理与一致性保障","description":"用订单、成交和账务事实共同判断结果。"},"headers":[],"relativePath":"06/0607/060007.md","filePath":"06/0607/060007.md"}'),i={name:"06/0607/060007.md"};function l(o,t,h,s,c,n){return a(),e("div",null,[...t[0]||(t[0]=[r('<div class="doc-eyebrow">现货手册 / TGEX KNOWLEDGE BASE</div><h1 id="异常处理与一致性保障" tabindex="-1">异常处理与一致性保障 <a class="header-anchor" href="#异常处理与一致性保障" aria-label="Permalink to &quot;异常处理与一致性保障&quot;">​</a></h1><div class="doc-lead">用订单、成交和账务事实共同判断结果。</div><h2 id="scenarios" tabindex="-1">典型场景 <a class="header-anchor" href="#scenarios" aria-label="Permalink to &quot;典型场景 {#scenarios}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>设计上应如何处理</th></tr></thead><tbody><tr><td>提交后超时</td><td>使用原业务标识查询，先确认是否受理</td></tr><tr><td>余额不足</td><td>拒绝占用，避免订单进入可成交状态</td></tr><tr><td>撤单时继续成交</td><td>按权威处理顺序确认剩余量，再解冻</td></tr><tr><td>成交消息重复</td><td>按成交唯一标识识别已处理结果</td></tr><tr><td>结算只完成部分动作</td><td>保留处理中状态与恢复任务，核对每条账务事实</td></tr><tr><td>撮合重启</td><td>恢复未完成委托及处理边界，避免重放已结算资金</td></tr></tbody></table><p>处理时建议明确权威顺序：撮合产出的成交与订单剩余量，优先于页面余额展示；账务流水用于解释可用/冻结为何如此，而不是由前端快照倒推订单状态。幂等键至少覆盖「同一业务编号的下单」与「同一成交标识的结算」。</p><h2 id="example" tabindex="-1">用贯穿示例核对 <a class="header-anchor" href="#example" aria-label="Permalink to &quot;用贯穿示例核对 {#example}&quot;">​</a></h2><p>沿「买入 0.01 BTC，成交 0.006，撤销 0.004」做一次结果核对：</p><ol><li>委托最终状态应为已撤销（或产品定义的等价终止态），已成交量 0.006，剩余 0。</li><li>成交记录存在一笔 0.006 BTC @ 60,000，金额 360 USDT。</li><li>买方可用 + 冻结 + 已支出 USDT 应回到可解释的 1,000 口径（忽略费用时：640 + 0 + 360）。</li><li>买方 BTC 增加 0.006；若有手续费，净增加量与费用流水一致。</li><li>卖方对称减少 0.006 BTC 占用，并增加对应 USDT（扣费前）。</li></ol><p>任何一项对不上，都不要只改余额；应先定位是委托状态、成交缺失，还是占用/解冻/入账缺一步。</p><h2 id="check" tabindex="-1">检查方法 <a class="header-anchor" href="#check" aria-label="Permalink to &quot;检查方法 {#check}&quot;">​</a></h2><p>沿业务编号核对委托、成交、占用、扣款与入账。只看页面余额或最后一条报错无法判断完整结果。异常修复应留下原因、审核和处理记录。</p><p>建议的最小检查清单：</p><table tabindex="0"><thead><tr><th>检查项</th><th>通过标准</th></tr></thead><tbody><tr><td>业务编号</td><td>能唯一定位到一笔委托</td></tr><tr><td>委托状态与数量</td><td>原始 = 已成交 + 剩余（终止后剩余为 0）</td></tr><tr><td>成交唯一标识</td><td>无重复结算</td></tr><tr><td>资金占用</td><td>冻结变化与剩余量、价格规则一致</td></tr><tr><td>入账流水</td><td>买卖双方资产变化可对齐同一成交</td></tr></tbody></table><p>这些是应满足的设计目标。工程中可见撮合恢复、事件处理和资金相关实现，但是否覆盖所有异常需要运行测试与部署核查。对账与资金一致性的一般方法，见<a href="/05/0503/050003">对账与资金一致性</a>。</p>',15)])])}const b=d(i,[["render",l]]);export{_ as __pageData,b as default};
